let _criaturaOrdem = true; // true = ascendente, false = descendente
const AMEACA_PESO = { Baixo:1, Alto:2, Altíssimo:3, Extremo:4, Catastrófico:5 };
const corAmeaca = { Baixo:'#22aa66', Alto:'#cc8822', Altíssimo:'#cc4422', Extremo:'#aa0000', Catastrófico:'#8b0000' };

function ordenarCriaturas(filtro, ordem){
  const sel = document.getElementById('sort-criaturas');
  const campo = (sel||{}).value || 'ameaca';
  const dir = ordem !== undefined ? ordem : _criaturaOrdem;
  const f = filtro !== undefined ? filtro : ((sel||{}).dataset.filtro||'todas');
  const multi = dir ? 1 : -1;
  CRIATURAS.sort((a,b)=>{
    let va = a[campo], vb = b[campo];
    if(campo==='ameaca'){ va = AMEACA_PESO[a.ameaca]||0; vb = AMEACA_PESO[b.ameaca]||0; }
    if(campo==='pv'||campo==='def'){ va = parseInt(a[campo])||0; vb = parseInt(b[campo])||0; }
    if(va < vb) return -1 * multi;
    if(va > vb) return 1 * multi;
    return 0;
  });
  renderCriaturas(f);
}

function toggleOrdemCriaturas(){
  _criaturaOrdem = !_criaturaOrdem;
  const btn = document.getElementById('btn-ordem');
  if(btn) btn.textContent = _criaturaOrdem ? '↑ Ameaça' : '⬇ Ameaça';
  ordenarCriaturas();
}

const TIPO_LABEL_CRIATURA = { basica:'Básica', 'outro-lado':'Outro Lado' };

function _criaturaFiltroAtual(){
  const sel = document.getElementById('sort-criaturas');
  return (sel && sel.dataset.filtro) || 'todas';
}

function renderCriaturas(filtro='todas'){
  const g = document.getElementById('criaturas-grid');
  if(!g) return;
  const sel = document.getElementById('sort-criaturas');
  if(sel) sel.dataset.filtro = filtro;

  const termo = (document.getElementById('cr-search-inp')?.value || '').trim().toLowerCase();
  let lista = filtro==='todas' ? CRIATURAS.slice() : CRIATURAS.filter(c=>c.tipo===filtro);
  if(termo) lista = lista.filter(c=>c.nome.toLowerCase().includes(termo));

  const count = document.getElementById('criaturas-count');
  if(count) count.textContent = `${lista.length} criatura${lista.length===1?'':'s'} encontrada${lista.length===1?'':'s'}`;

  if(!lista.length){
    g.innerHTML = `<div class="cr-empty">☠ Nenhuma criatura corresponde à busca.</div>`;
    return;
  }

  g.innerHTML = lista.map(cr=>{
    const cor = corAmeaca[cr.ameaca]||'#888';
    return `
    <div class="cr-card" onclick="verCriatura('${cr.id}')">
      <div class="cr-card-bar" style="background:${cor}"></div>
      <div class="cr-card-body">
        <div class="cr-card-head">
          <div class="cr-card-name">${cr.nome}</div>
          <span class="cr-badge" style="border-color:${cor};color:${cor}">${cr.ameaca}</span>
        </div>
        <div class="cr-tipo-tag">${TIPO_LABEL_CRIATURA[cr.tipo]||cr.tipo}</div>
        <div class="cr-stats-row">
          <span>PV <b style="color:var(--crimson-mid)">${cr.pv}</b></span>
          <span>DEF <b style="color:var(--white-ash)">${cr.def}</b></span>
        </div>
        <div class="cr-card-desc">${cr.desc.substring(0,80)}…</div>
        <div class="cr-card-cta">VER FICHA COMPLETA →</div>
      </div>
    </div>`;
  }).join('');
}

function verCriatura(id){
  const cr = CRIATURAS.find(c=>c.id===id);
  if(!cr) return;
  const cor = corAmeaca[cr.ameaca]||'#888';

  let html = `
    <div class="cr-det-head">
      <div class="cr-det-name">${cr.nome}</div>
      <span class="cr-badge" style="border-color:${cor};color:${cor};font-size:11px;padding:4px 12px">Ameaça ${cr.ameaca}</span>
    </div>
    <div class="cr-det-tipo">${TIPO_LABEL_CRIATURA[cr.tipo]||cr.tipo}</div>
    <p class="cr-det-desc">${cr.desc}</p>`;

  // ── PV / Defesa — MESMAS classes .stat-box/.snum/.defesa-val da ficha de player ──
  html += `<div class="stat-grid" style="grid-template-columns:repeat(2,minmax(0,1fr));margin-bottom:16px">
    <div class="stat-box vital-box">
      <div class="stat-name">Pontos de Vida</div>
      <span class="snum pv">${cr.pv}</span>
    </div>
    <div class="stat-box defesa-box">
      <div class="stat-name">Defesa</div>
      <div class="defesa-val">${cr.def}</div>
    </div>
  </div>`;

  // ── Atributos — MESMA roda hexagonal da ficha de player (somente leitura, sem botões +/-) ──
  html += `<div class="attr-hex-wrap" style="margin-bottom:10px">
    <svg class="attr-hex-bg" viewBox="0 0 280 240" preserveAspectRatio="xMidYMid meet">
      <polygon points="140,6 262,74 262,178 140,234 18,178 18,74" fill="none" stroke="var(--blood-deep)" stroke-width="1.4"/>
      <polygon points="140,30 234,84 234,168 140,214 46,168 46,84" fill="none" stroke="var(--crimson)" stroke-width="0.6" opacity="0.3"/>
    </svg>
    <div class="attr-hex-center">ATRIBUTOS</div>`;
  ATTRS.forEach(full=>{
    const abbr = ATTR_ABBR[full];
    const pos = ATTR_POS[full];
    const val = cr.atributos[abbr] ?? '—';
    html += `<div class="attr-node" style="top:${pos.top};left:${pos.left}">
      <div class="attr-node-circle"><span class="attr-node-val">${val}</span></div>
      <div class="attr-node-label">${abbr}</div>
    </div>`;
  });
  html += `</div>`;

  // ── Ataque — MESMA tabela/linha .ataque-row da ficha de player ──
  const ataques = cr.atq.split(' / ').map(s=>s.trim()).filter(Boolean);
  html += `<div class="cr-sec-label">Ataque</div>
    <div style="display:flex;flex-direction:column;gap:3px;margin-bottom:16px">
      ${ataques.map(a=>`<div class="ataque-row" style="grid-template-columns:1fr"><div class="ataque-col-arma">${a}</div></div>`).join('')}
    </div>`;

  // ── Habilidades — MESMO list-item/badge da ficha de player ──
  html += `<div class="cr-sec-label">Habilidades</div>
    <div>${cr.habs.map(h=>`<div class="list-item"><div class="list-body"><span class="badge badge-h">Habilidade</span>${h}</div></div>`).join('')}</div>`;

  abrirModalDetalhe(html);
}

function filtrarCriaturas(tipo){
  const t = tipo !== undefined ? tipo : _criaturaFiltroAtual();
  if(tipo !== undefined){
    ['todas','basica','outro-lado'].forEach(k=>{
      const b = document.getElementById('fil-'+k);
      if(b) b.dataset.active = (k===t) ? 'true' : 'false';
    });
  }
  ordenarCriaturas(t);
}

