function renderReliquias(filtro='todas'){
  const g = document.getElementById('reliquias-grid');
  if(!g) return;
  const lista = filtro==='todas' ? RELIQUIAS : RELIQUIAS.filter(r=>r.elemento===filtro);
  const elNome = {sangue:'<span class="sym-el sym-sangue" title="Sangue"></span> Sangue', energia:'<span class="sym-el sym-energia" title="Energia"></span> Energia', conhecimento:'<span class="sym-el sym-conhecimento" title="Conhecimento"></span> Conhecimento', morte:'<span class="sym-el sym-morte" title="Morte"></span> Morte'};

  if(!lista.length){
    g.innerHTML = `<div class="cr-empty">◇ Nenhuma relíquia neste filtro.</div>`;
    return;
  }

  g.innerHTML = lista.map(r=>{
    const icone = r.icone.includes('sym-el')
      ? r.icone.replace('class="sym-el ', `style="display:block;width:100%;height:90px;background-size:${r.elemento==='conhecimento'?'65%':r.elemento==='medo'?'95%':'85%'};background-repeat:no-repeat;background-position:center;mix-blend-mode:screen;filter:brightness(1.2) drop-shadow(0 0 8px ${r.cor}88);opacity:0.85" class="sym-el `)
      : `<div style="font-size:36px">${r.icone}</div>`;
    return `
    <div class="cr-rel-card" style="border-color:${r.cor};color:${r.cor}" onclick="verReliquia('${r.id}')">
      <div class="cr-rel-top" style="background:linear-gradient(90deg,transparent,${r.cor},transparent)"></div>
      <div class="cr-rel-body">
        <div class="cr-rel-icon-wrap">${icone}</div>
        <div class="cr-rel-name">${r.nome}</div>
        <div class="cr-rel-meta">
          <span class="cr-rel-el-tag" style="border-color:${r.cor};color:${r.cor}">${elNome[r.elemento]||r.elemento}</span>
          <span class="cr-rel-portador">⛧ ${r.portador_titulo}</span>
        </div>
        <div class="cr-rel-desc" style="border-color:${r.cor}55">${r.forma_fisica.substring(0,90)}…</div>
        <div class="cr-rel-cta" style="color:${r.cor}">VER PORTADORES →</div>
      </div>
    </div>`;
  }).join('');
}

